return function(B,test)
 local Clock=require('realtime');local V=require('vessels');local T=require('desktop_samples');local M=require('desktop_model');local G=require('genome');local Store=require('desktop_store')
 local function state() local s=B.new(20261112);B.collect(s);V.ensure(s);M.ensure(s);require('desktop_worlds').ensure(s);return s end
 local function growing() local s=state();local v=s.vessels[1];assert(T.seed(s,v.id,1));Clock.start(s,nil,1000,0);return s,v end
 local function advance(s,seconds) s.clock.pendingSeconds=s.clock.pendingSeconds+seconds;while s.clock.pendingSeconds>.000001 do Clock.process(s,B.update) end end
 test('One PC second counts once, independent of frame count or clock observation frequency',function()
  local a,b=state(),state();Clock.start(a,nil,1000,0);Clock.start(b,nil,1000,0)
  for i=1,100 do Clock.update(a,B.update,1000+i/10,i/10) end;Clock.update(b,B.update,1010,10)
  assert(math.abs(a.clock.elapsedSeconds-10)<1e-7 and math.abs(b.clock.elapsedSeconds-10)<1e-7);assert(math.abs(a.time*60-10)<.051 and math.abs(a.time-b.time)<1e-7)
 end)
 test('Hidden laboratory still advances by actual PC time',function() local s,v=growing();s.desktop.groups.laboratory=false;Clock.update(s,B.update,1060,60);assert(math.abs(s.time-1)<1e-7 and math.abs(v.cultureAge-1)<1e-7 and v.progress>0 and not s.desktop.groups.laboratory) end)
 test('Sleep and stalled frames are not clamped to a tenth of a second',function() local s=state();Clock.start(s,nil,1000,0);Clock.update(s,B.update,1120,.1);assert(math.abs(s.clock.elapsedSeconds-120)<1e-7 and math.abs(s.time-2)<1e-7) end)
 test('Backward PC clock changes never reverse life or duplicate elapsed seconds',function() local s=state();Clock.start(s,nil,1000,0);Clock.update(s,B.update,1010,10);Clock.update(s,B.update,900,11);Clock.update(s,B.update,901,12);assert(s.clock.elapsedSeconds==12 and s.clock.lastSeenUnix>=1012);Clock.update(s,B.update,901,12);assert(s.clock.elapsedSeconds==12) end)
 test('Offline elapsed time is queued in full instead of using the old five-minute cap',function() local s=state();Clock.ensure(s,1000);Clock.start(s,1000,1000+86400,0);assert(s.clock.pendingSeconds==86400);local advanced=0;Clock.process(s,function(_,minutes) advanced=advanced+minutes*60 end,300);assert(advanced==300 and s.clock.pendingSeconds==86100 and Clock.busy(s)) end)
 test('Pending elapsed time survives saving during catch-up without being counted twice',function() local s=state();Clock.start(s,nil,1000,0);Clock.observe(s,2000,1000);Clock.process(s,B.update,300);local restored=assert(Store.decode(Store.payload(s,2000),B));Clock.start(restored,2000,2060,0);assert(math.abs(restored.clock.pendingSeconds-760)<1e-7 and restored.clock.elapsedSeconds==300) end)
 test('Old save migration preserves progress and starts PC tracking on upgrade',function() local s=state();s.time=20;local cells=require('persistence').encode(s.cells);Clock.start(s,1000,1000000,0);assert(s.clock.pendingSeconds==0 and s.clock.elapsedSeconds==1200 and s.clock.migratedFromLegacy);assert(require('persistence').encode(s.cells)==cells) end)
 test('Fed Petri cells divide automatically with a real countdown and no start or harvest loop',function() local s,v=growing();assert(not v.cultivating);local info=V.growthInfo(v);assert(info.status=='Growing' and info.nextCellSeconds>60);local initial=V.count(v);advance(s,info.nextCellSeconds+10);assert(V.count(v)>initial and v.nutrients<1 and v.totalBirths>=1);local second=V.growthInfo(v);assert(second.status=='Growing' and second.nextCellSeconds>0) end)
 test('Food exhaustion stops growth and adding food resumes automatically',function() local s,v=growing();v.nutrients=0;local initial=V.count(v);advance(s,60);assert(V.count(v)==initial and V.growthInfo(v).status=='Needs food');assert(T.action(s,v.id,'feed'));local info=V.growthInfo(v);advance(s,info.nextCellSeconds+15);assert(V.count(v)>initial) end)
 test('Continuous culture does not hit an invisible old batch replication counter',function() local s,v=growing();v.contents[1].cell.replicationCapacity=0;local info=V.growthInfo(v);advance(s,info.nextCellSeconds+15);assert(V.count(v)>1 and V.count(v)<=V.types[v.kind].capacity) end)
 test('Capacity and freezing stop growth without creating or losing cells',function() local s,v=growing();v.contents[1].count=V.types[v.kind].capacity;advance(s,60);assert(V.count(v)==V.types[v.kind].capacity and V.growthInfo(v).status=='Full');v.frozen=true;local before=require('persistence').encode(v);advance(s,120);assert(require('persistence').encode(v)==before and V.growthInfo(v).status=='Frozen') end)
 test('Embryos, gametes and organism ages all follow real elapsed time',function()
  local s=state();Clock.start(s,nil,1000,0);local g=G.copy(require('audit_examples').compact.genome);local embryo=assert(B.queue(s,g,'clock test',0));assert(B.precursor(s,1,'Egg'));local o=assert(B.spawn(s,g,'clock test',0));o.worldId='terrarium';advance(s,120)
  assert(math.abs(o.age-2)<.001 and math.abs(s.gametes[1].progress-.25)<.001 and embryo.progress>0 and embryo.progress<.2)
 end)
 test('Countdown formatting uses actual elapsed durations rather than simulated-hour labels',function() assert(Clock.duration(61)=='01:01' and Clock.duration(3601)=='01:00:01' and Clock.biologyDuration(8)=='08:00');assert(not V.timerText(select(2,growing())):find('hour')) end)
end
